import { useRef } from 'react'
import { useLang } from '../lib/i18n'
import { gsap, prefersReduced, useGsap } from '../lib/gsap'
import { ui } from '../content/ui'
import { Eyebrow, Lines, dot } from '../components/Brand'

export function Principles() {
  const { tr } = useLang()

  return (
    <ol className="grid gap-x-10 sm:grid-cols-2">
      {ui.about.principles.map((principle, i) => (
        <li
          key={principle.t.en}
          className="group border-t border-white/15 py-7 transition-colors duration-500 hover:border-signal"
          data-reveal="up"
          data-delay={i * 0.06}
        >
          <div className="flex items-start gap-4">
            <span
              className="mt-2.5 block h-2 w-2 shrink-0 rounded-full bg-signal transition-transform duration-500 ease-cine group-hover:scale-[2.2]"
              aria-hidden="true"
            />

            <div className="min-w-0">
              {/* Principle title — bold */}
              <h3 className="text-xl font-bold leading-snug tracking-tight lg:text-[1.375rem] rtl:tracking-normal">
                {tr(principle.t)}
              </h3>

              {/* Description — larger and bolder */}
              <p className="mt-3 max-w-[30ch] text-[1.0625rem] font-semibold leading-relaxed text-white/95 lg:text-[1.125rem]">
                {tr(principle.d)}
              </p>
            </div>
          </div>
        </li>
      ))}
    </ol>
  )
}

/** Character portrait with scroll animation. */
export function CharacterPortrait({
  className = '',
}: {
  className?: string
}) {
  const { tr } = useLang()
  const root = useRef<HTMLElement>(null)

  useGsap(root, () => {
    if (prefersReduced()) return

    gsap.fromTo(
      '.cp-img',
      {
        yPercent: -7,
        scale: 1.12,
      },
      {
        yPercent: 7,
        scale: 1.12,
        ease: 'none',
        scrollTrigger: {
          trigger: root.current,
          start: 'top bottom',
          end: 'bottom top',
          scrub: true,
        },
      },
    )

    gsap.fromTo(
      '.cp-a',
      {
        strokeDashoffset: 1,
      },
      {
        strokeDashoffset: 0,
        ease: 'none',
        scrollTrigger: {
          trigger: root.current,
          start: 'top 80%',
          end: 'center 45%',
          scrub: 0.6,
        },
      },
    )
  })

  return (
    <figure
      ref={root}
      className={`relative ${className}`}
    >
      {/* Outline around the portrait */}
      <svg
        viewBox="0 0 400 520"
        className="absolute -inset-x-[14%] -top-[8%] h-[116%] w-[128%]"
        aria-hidden="true"
      >
        <path
          className="cp-a"
          d="M10 520 200 10 390 520"
          pathLength={1}
          strokeDasharray="1"
          fill="none"
          stroke="#F6620D"
          strokeWidth="2"
        />
      </svg>

      <div
        className="relative aspect-[3/4] overflow-hidden rounded-[2rem]"
        data-reveal="clip"
      >
        <img
          className="cp-img h-full w-full object-cover object-[50%_22%]"
          src="/media/character.webp"
          width={720}
          height={1280}
          loading="lazy"
          decoding="async"
          srcSet="/media/character-480.webp 480w, /media/character.webp 720w"
          sizes="(max-width: 640px) 300px, 420px"
          alt={tr(ui.about.charAlt)}
        />

        <div className="absolute inset-0 bg-gradient-to-t from-navy-deep/80 via-transparent to-transparent" />
      </div>

      {/* Caption — larger and bolder */}
      <figcaption className="mt-5 flex max-w-[34ch] items-start gap-3 text-base font-semibold leading-relaxed text-white/95 sm:text-[1.0625rem]">
        <span
          className="sphere mt-2 block h-2.5 w-2.5 shrink-0"
          aria-hidden="true"
        />

        <span>{tr(ui.about.charNote)}</span>
      </figcaption>
    </figure>
  )
}

/** Home teaser. */
export function About() {
  const { tr, lang } = useLang()

  return (
    <section className="section overflow-x-clip">
      <div className="wrap grid items-center gap-14 lg:grid-cols-[0.8fr_1.2fr] lg:gap-24">
        <CharacterPortrait className="order-2 mx-auto w-full max-w-[300px] sm:max-w-[420px] lg:order-1" />

        <div className="order-1 min-w-0 lg:order-2">
          {/* Section label — larger and bold */}
          <Eyebrow className="mb-7 !text-[0.95rem] !font-bold !text-white lg:!text-[1rem]">
            {tr(ui.about.eyebrow)}
          </Eyebrow>

          <h2 className="sr-only">
            {ui.about.title[lang].join(' ')}
          </h2>

          {/* Smaller heading — both lines bold */}
          <Lines
            as="p"
            className="t-display !text-[clamp(1.75rem,5.5vw,2.75rem)] !font-bold lg:!text-[clamp(2rem,3.9vw,4rem)]"
            lines={[
              <span key="first" className="!font-bold">
                {ui.about.title[lang][0]}
              </span>,
              <span key="second" className="!font-bold">
                {dot(ui.about.title[lang][1])}
              </span>,
            ]}
          />

          {/* Main subtitle — larger and bolder */}
          <p
            className="t-lead mt-7 max-w-[46ch] !text-[1.125rem] !font-semibold !leading-[1.75] text-white sm:!text-[1.25rem] lg:!text-[1.375rem]"
            data-reveal="up"
          >
            {tr(ui.about.lead)}
          </p>

          <div className="mt-10">
            <Principles />
          </div>
        </div>
      </div>
    </section>
  )
}
